func findWords(_ board: [[Character]], _ words: [String]) -> [String] {
    final class Node { var kids: [Character: Node] = [:]; var word: String? }
    let root = Node()
    for w in words {
        var n = root
        for c in w { if n.kids[c] == nil { n.kids[c] = Node() }; n = n.kids[c]! }
        n.word = w
    }
    var grid = board, found: [String] = []
    let rows = grid.count, cols = grid[0].count
    func dfs(_ r: Int, _ c: Int, _ parent: Node) {
        let ch = grid[r][c]
        guard let node = parent.kids[ch] else { return }
        if let w = node.word { found.append(w); node.word = nil }
        grid[r][c] = "#"
        for (dr, dc) in [(1, 0), (-1, 0), (0, 1), (0, -1)] {
            let nr = r + dr, nc = c + dc
            if nr >= 0, nr < rows, nc >= 0, nc < cols, grid[nr][nc] != "#" { dfs(nr, nc, node) }
        }
        grid[r][c] = ch
        if node.kids.isEmpty && node.word == nil { parent.kids[ch] = nil }   // prune
    }
    for r in 0..<rows { for c in 0..<cols { dfs(r, c, root) } }
    return found
}
